void foo1(int n) {                      // O(n): printf körs n gånger
    for (int i = 0; i < n; i++) printf("%d\n", i);
}

void foo2(int n) {                      // O(1): alltid 100 gånger, oavsett n
    for (int i = 0; i < 100; i++) printf("%d\n", i);
}

void foo3(int n) {                      // O(n^2): n gånger n
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) printf("%d\n", i);
}

void foo4(int n) {                      // O(log n): i dubblas varje varv
    for (int i = 1; i < n; i *= 2) printf("%d\n", i);
}

int foo5(int n) {                       // O(2^n): varje anrop gör två nya
    if (n == 0) return 1;
    return foo5(n - 1) + foo5(n - 1);
}
